142	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, errorOf(() -> service.receiptCopy(reservation.id())));
143	
144	        service.confirm(reservation.id());
145	
146	        assertEquals("Comprovante de reserva", service.receiptCopy(reservation.id()).title());
147	    }
