        assertEquals(messagesAfterConfirmation + 3, sentMessages.all().size());
        sent = sentMessages.all();
        assertEquals("governanca@pousadamarealta.com.br", sent.get(sent.size() - 1).to());
        assertEquals("Reserva cancelada - quarto 102", sent.get(sent.size() - 1).subject());
    }

